다음 코드에서 left=22이고 right=21일 때, 문장 커버리지로 가장 적절한 것은? (단, 각 라인에 번호가 부여된 것을 문장으로 간주한다.)

public int play(int left, int right) {
1   int ln = left;
2   int rn = right;
3   if (ln > 21)
4       ln = 0;
5   if (rn > 21)
6       rn = 0;
7   if (ln > rn)
8       return ln;
9   else
10      return rn;
}

